SPEAKER_PORTAL_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light">\n  <title>Speaker portal · SessionBuddy</title>\n  <link rel="stylesheet" href="/speaker/assets/speaker.css?v=8">\n  <link rel="stylesheet" href="/app-shell/assets/app-shell.css?v=3">\n  <script src="/app-shell/assets/app-shell.js?v=4" defer></script>\n  <script src="/speaker/assets/speaker-portal.js?v=7" defer></script>\n</head>\n<body class="app-body">\n  <a class="skip-link" href="#main">Skip to content</a>\n  <header data-auth-shell data-allow-guest></header>\n\n  <main id="main" class="shell" tabindex="-1">\n    <div id="status" class="status" role="status" aria-live="polite">\n      Loading your speaker portal…\n    </div>\n\n    <section id="auth-state" class="state-panel" hidden aria-labelledby="auth-title">\n      <h1 id="auth-title">Speaker sign in</h1>\n      <p>Use the email address connected to your invitation or proposal.</p>\n      <button id="speaker-sign-in" type="button">Sign in</button>\n    </section>\n\n    <div id="portal" hidden>\n      <section id="overview" class="hero" aria-labelledby="portal-title">\n        <div>\n          <h1 id="portal-title">Your speaker portal</h1>\n          <p id="event-summary" class="lede"></p>\n          <p id="event-timezone" class="timezone"></p>\n        </div>\n        <div class="progress-card">\n          <span id="progress-label">Onboarding progress</span>\n          <strong id="progress-count">0 of 0 complete</strong>\n          <progress id="progress" value="0" max="1" aria-labelledby="progress-label progress-count"></progress>\n          <p id="next-deadline">No upcoming deadline.</p>\n        </div>\n      </section>\n\n      <div class="portal-grid">\n        <section id="tasks" class="panel" aria-labelledby="tasks-title">\n          <div class="section-heading">\n            <h2 id="tasks-title">Outstanding tasks</h2>\n            <span id="task-count" class="count-badge">0</span>\n          </div>\n          <ul id="task-list" class="item-list" aria-describedby="task-help"></ul>\n          <p id="task-help" class="help">Completing the destination action completes its task automatically.</p>\n        </section>\n\n        <section id="submissions" class="panel" aria-labelledby="submissions-title">\n          <div class="section-heading">\n            <h2 id="submissions-title">Submissions</h2>\n          </div>\n          <ul id="submission-list" class="item-list"></ul>\n        </section>\n\n        <section id="resources" class="panel profile-panel" aria-labelledby="resources-title">\n          <div class="section-heading"><h2 id="resources-title">Resources</h2><span id="resource-count" class="count-badge">0</span></div>\n          <p class="help">Guides, venue details, and documents shared by your event team.</p>\n          <div id="resource-list" class="resource-list"><p class="empty">Loading resources…</p></div>\n        </section>\n\n        <section id="profile" class="panel profile-panel" aria-labelledby="profile-title">\n          <h2 id="profile-title">Profile</h2>\n          <p class="help">Required fields are marked “required.” Changes apply to your shared speaker profile, not past proposal answers.</p>\n          <div id="error-summary" class="error-summary" role="alert" tabindex="-1" hidden>\n            <h3>Check your profile</h3><ul></ul>\n          </div>\n          <form id="profile-form" novalidate>\n            <div class="form-grid">\n              <label for="display-name">Name <span>required</span></label>\n              <div><input id="display-name" name="display_name" autocomplete="name" maxlength="200" required aria-describedby="display-name-error"><p id="display-name-error" class="field-error"></p></div>\n              <label for="job-title">Job title</label>\n              <div><input id="job-title" name="job_title" autocomplete="organization-title" maxlength="200" aria-describedby="job-title-error"><p id="job-title-error" class="field-error"></p></div>\n              <label for="company">Company</label>\n              <div><input id="company" name="company" autocomplete="organization" maxlength="200" aria-describedby="company-error"><p id="company-error" class="field-error"></p></div>\n              <label for="location">Location</label>\n              <div><input id="location" name="location" autocomplete="address-level2" maxlength="200" aria-describedby="location-error"><p id="location-error" class="field-error"></p></div>\n              <label for="website">Website</label>\n              <div><input id="website" name="website" type="url" inputmode="url" autocomplete="url" placeholder="https://example.com" maxlength="500" aria-describedby="website-error"><p id="website-error" class="field-error"></p></div>\n              <label for="biography">Biography <span>required</span></label>\n              <div><textarea id="biography" name="biography" rows="7" maxlength="5000" required aria-describedby="biography-help biography-count biography-error"></textarea><div class="field-meta"><p id="biography-help" class="help">Write a short introduction for event materials.</p><p id="biography-count" class="help">0 of 5,000 characters</p></div><p id="biography-error" class="field-error"></p></div>\n            </div>\n            <div id="stale-warning" class="stale-warning" role="alert" tabindex="-1" hidden>\n              <strong>Your profile changed elsewhere.</strong>\n              <p>Reload the latest version before saving again. Copy any unsaved text first.</p>\n              <button id="reload-profile" class="secondary" type="button">Reload latest profile</button>\n            </div>\n            <div class="actions"><button id="save-profile" type="submit">Save profile</button></div>\n          </form>\n        </section>\n\n        <section id="assets" class="panel profile-panel" aria-labelledby="assets-title">\n          <h2 id="assets-title">Files</h2>\n          <p class="help">Files stay private while they are checked. Only the latest clean version becomes current.</p>\n          <div id="asset-status" class="inline-status" role="status" aria-live="polite">Loading current assets…</div>\n          <ul id="asset-list" class="asset-list"><li>Loading…</li></ul>\n          <div class="upload-grid">\n            <form class="upload-card" data-kind="headshot">\n              <h3>Headshot</h3><p>JPEG, PNG, or WebP · up to 5 MB</p>\n              <label for="headshot-file">Choose headshot</label>\n              <input id="headshot-file" name="file" type="file" accept="image/jpeg,image/png,image/webp" required>\n              <button type="submit">Upload headshot</button>\n              <progress max="100" value="0" hidden aria-label="Headshot upload progress"></progress>\n              <p class="upload-status" role="status"></p>\n            </form>\n            <form class="upload-card" data-kind="slides">\n              <h3>Slides</h3><p>PDF, PowerPoint, or OpenDocument · up to 50 MB</p>\n              <label for="slides-submission">Session</label><select id="slides-submission" name="submission_id" required><option value="">Choose a session</option></select>\n              <label for="slides-file">Choose slides</label>\n              <input id="slides-file" name="file" type="file" accept="application/pdf,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation,application/vnd.oasis.opendocument.presentation" required>\n              <button type="submit">Upload slides</button>\n              <progress max="100" value="0" hidden aria-label="Slides upload progress"></progress>\n              <p class="upload-status" role="status"></p>\n            </form>\n            <form class="upload-card" data-kind="supporting_document">\n              <h3>Supporting document</h3><p>PDF · up to 20 MB</p>\n              <label for="document-submission">Session</label><select id="document-submission" name="submission_id" required><option value="">Choose a session</option></select>\n              <label for="document-file">Choose document</label>\n              <input id="document-file" name="file" type="file" accept="application/pdf" required>\n              <button type="submit">Upload document</button>\n              <progress max="100" value="0" hidden aria-label="Document upload progress"></progress>\n              <p class="upload-status" role="status"></p>\n            </form>\n          </div>\n        </section>\n      </div>\n    </div>\n  </main>\n</body>\n</html>\n'

SPEAKER_PORTAL_JS = '(() => {\n  "use strict";\n  const state = { csrf: "", portal: null, version: null };\n  const uploadRules = {\n    headshot: { max: 5 * 1024 * 1024, types: new Set(["image/jpeg", "image/png", "image/webp"]) },\n    slides: { max: 50 * 1024 * 1024, types: new Set(["application/pdf", "application/vnd.ms-powerpoint", "application/vnd.openxmlformats-officedocument.presentationml.presentation", "application/vnd.oasis.opendocument.presentation"]) },\n    supporting_document: { max: 20 * 1024 * 1024, types: new Set(["application/pdf"]) }\n  };\n  const byId = (id) => document.getElementById(id);\n  const make = (tag, text, className) => {\n    const node = document.createElement(tag);\n    if (text !== undefined) node.textContent = text;\n    if (className) node.className = className;\n    return node;\n  };\n\n  function setStatus(message, kind = "") {\n    const status = byId("status");\n    status.textContent = message;\n    status.className = `status${kind ? ` ${kind}` : ""}`;\n  }\n\n  function recordTelemetry(started, response) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = innerWidth;\n    window.__sessionbuddyTelemetryDraft = {\n      schema_version: 1, page_template: "/speaker",\n      navigation_type: navigation?.type || "unknown",\n      device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop",\n      sampled: false, lcp_ms: null, inp_ms: null, cls: null,\n      ttfb_ms: navigation?.responseStart ?? null, fcp_ms: null,\n      route_transition_ms: null, critical_api_ms: Math.max(0, performance.now() - started),\n      api_request_id: response.headers.get("x-request-id")\n    };\n  }\n\n  async function api(path, options = {}) {\n    const started = performance.now();\n    const response = await fetch(path, { credentials: "same-origin", ...options });\n    recordTelemetry(started, response);\n    let body = null;\n    if (response.status !== 204) {\n      try { body = await response.json(); } catch (_) { body = null; }\n    }\n    if (!response.ok) {\n      const error = new Error(body?.error?.message || `Request failed (${response.status})`);\n      error.status = response.status;\n      error.details = body?.error?.details || [];\n      throw error;\n    }\n    return body;\n  }\n\n  function formatDate(value, timezone) {\n    if (!value) return "No due date";\n    try {\n      return new Intl.DateTimeFormat(undefined, {\n        dateStyle: "medium", timeStyle: "short", timeZone: timezone\n      }).format(new Date(value));\n    } catch (_) { return "Date unavailable"; }\n  }\n\n  function taskDestination(task) {\n    // Only same-page destinations are accepted; arbitrary API-provided URLs are never used.\n    if (["#profile", "#tasks", "#submissions", "#assets"].includes(task.destination_path)) {\n      return task.destination_path;\n    }\n    if (["profile", "biography"].includes(task.task_type)) return "#profile";\n    if (["headshot", "slides", "supporting_document"].includes(task.task_type)) return "#assets";\n    return "#tasks";\n  }\n\n  function customTaskForm(task) {\n    const form = make("form", undefined, "task-form");\n    form.dataset.taskId = task.id;\n    for (const field of task.form_fields || []) {\n      const label = make("label", field.label);\n      let input;\n      if (field.type === "textarea") input = document.createElement("textarea");\n      else if (field.type === "select") {\n        input = document.createElement("select");\n        input.append(new Option("Choose…", ""));\n        (field.choices || []).forEach((choice) => input.add(new Option(choice, choice)));\n      } else {\n        input = document.createElement("input");\n        input.type = field.type === "checkbox" ? "checkbox" : field.type === "url" ? "url" : "text";\n        if (field.type === "checkbox") label.classList.add("check-label");\n      }\n      input.name = field.key;\n      input.required = Boolean(field.required);\n      label.append(input);\n      form.append(label);\n    }\n    const submit = make("button", task.form_fields?.length ? "Send response" : "Mark complete");\n    submit.type = "submit";\n    form.append(submit);\n    form.addEventListener("submit", async (event) => {\n      event.preventDefault();\n      submit.disabled = true;\n      const values = {};\n      for (const field of task.form_fields || []) {\n        const input = form.elements.namedItem(field.key);\n        values[field.key] = field.type === "checkbox" ? Boolean(input.checked) : input.value;\n      }\n      try {\n        await api(`/api/v1/speaker/tasks/${encodeURIComponent(task.id)}/response`, {\n          method: "POST",\n          headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` },\n          body: JSON.stringify({ answers: values, version: task.version })\n        });\n        const portal = await api("/api/v1/speaker/portal");\n        renderPortal(portal);\n        announceOnboardingChange();\n        setStatus("Task completed.", "success");\n      } catch (error) {\n        setStatus(error.status === 409 ? "This task changed. Reload the portal and try again." : error.message, "error");\n        submit.disabled = false;\n      }\n    });\n    return form;\n  }\n\n  function renderTasks(tasks, timezone) {\n    const list = byId("task-list");\n    list.replaceChildren();\n    const outstanding = tasks.filter((task) => !["completed", "waived"].includes(task.state));\n    byId("task-count").textContent = String(outstanding.length);\n    if (!outstanding.length) {\n      list.append(make("li", "You’re all caught up. There are no outstanding tasks.", "empty"));\n      return;\n    }\n    outstanding.forEach((task) => {\n      const item = make("li", undefined, "item-card");\n      const heading = make("h3", task.title);\n      const help = task.help_text ? make("p", task.help_text) : null;\n      const meta = make("p", undefined, "item-meta");\n      const overdue = task.due_at_ms !== null && task.due_at_ms < Date.now();\n      const dueSoon = task.due_at_ms !== null && task.due_at_ms >= Date.now()\n        && task.due_at_ms - Date.now() <= 7 * 24 * 60 * 60 * 1000;\n      const stateText = overdue ? "Overdue" : dueSoon ? "Due soon" : "Outstanding";\n      meta.append(\n        make("span", stateText, `state-badge${overdue ? " overdue" : ""}`),\n        make("span", `Due ${formatDate(task.due_at_ms, timezone)} · ${timezone}`)\n      );\n      item.append(heading);\n      if (help) item.append(help);\n      item.append(meta);\n      if (task.task_type === "custom") {\n        item.append(customTaskForm(task));\n      } else {\n        const action = make("a", task.action_label || "Complete task", "task-link");\n        action.href = taskDestination(task);\n        item.append(action);\n      }\n      list.append(item);\n    });\n  }\n\n  function renderSubmissions(submissions) {\n    const list = byId("submission-list");\n    list.replaceChildren();\n    if (!submissions.length) {\n      list.append(make("li", "No proposals are connected to this account yet.", "empty"));\n      return;\n    }\n    submissions.forEach((submission) => {\n      const item = make("li", undefined, "item-card");\n      item.append(\n        make("h3", submission.proposal_title),\n        make("p", submission.status.replaceAll("_", " "), `state-badge${submission.status === "accepted" ? " success" : ""}`)\n      );\n      list.append(item);\n    });\n  }\n\n  function fillSubmissionChoices(submissions) {\n    ["slides-submission", "document-submission"].forEach((id) => {\n      const select = byId(id);\n      const selected = select.value;\n      select.replaceChildren(new Option("Choose a session", ""));\n      submissions.forEach((submission) => select.add(new Option(submission.proposal_title, submission.id)));\n      if ([...select.options].some((option) => option.value === selected)) select.value = selected;\n    });\n  }\n\n  function fillProfile(profile) {\n    const form = byId("profile-form");\n    ["display_name", "job_title", "company", "location", "biography"].forEach((name) => {\n      form.elements[name].value = profile[name] || "";\n    });\n    form.elements.website.value = profile.links?.[0] || "";\n    state.version = profile.version;\n    updateBiographyCount();\n    clearErrors();\n    byId("stale-warning").hidden = true;\n  }\n\n  function renderPortal(portal) {\n    state.portal = portal;\n    const event = portal.event;\n    byId("portal-title").textContent = `Welcome, ${portal.profile.display_name || "speaker"}`;\n    const eventDates = `${formatDate(event.starts_at_ms, event.time_zone)}–${formatDate(event.ends_at_ms, event.time_zone)}`;\n    byId("event-summary").textContent = `${event.name} · ${eventDates}`;\n    byId("event-timezone").textContent = `All deadlines shown in ${event.time_zone}.`;\n    const tasks = portal.tasks || [];\n    const completed = portal.completed_tasks;\n    const total = portal.total_tasks;\n    byId("progress-count").textContent = `${completed} of ${total} complete`;\n    byId("progress").max = Math.max(total, 1);\n    byId("progress").value = completed;\n    const upcoming = tasks.filter((task) => task.state === "open" && task.due_at_ms !== null)\n      .sort((left, right) => left.due_at_ms - right.due_at_ms)[0];\n    byId("next-deadline").textContent = upcoming\n      ? `Next: ${upcoming.title}, ${formatDate(upcoming.due_at_ms, event.time_zone)} · ${event.time_zone}`\n      : "No upcoming deadline.";\n    renderTasks(tasks, event.time_zone);\n    renderSubmissions(portal.submissions || []);\n    fillSubmissionChoices(portal.submissions || []);\n    fillProfile(portal.profile);\n    byId("auth-state").hidden = true;\n    byId("portal").hidden = false;\n  }\n\n  function announceOnboardingChange() {\n    const eventId = state.portal?.event?.id;\n    if (!eventId || !("BroadcastChannel" in window)) return;\n    const channel = new BroadcastChannel(`sessionbuddy:onboarding:${eventId}`);\n    channel.postMessage({ type: "snapshot-invalidated" });\n    channel.close();\n  }\n\n  function clearErrors() {\n    byId("error-summary").hidden = true;\n    byId("error-summary").querySelector("ul").replaceChildren();\n    byId("profile-form").querySelectorAll("[aria-invalid]").forEach((field) => field.removeAttribute("aria-invalid"));\n    byId("profile-form").querySelectorAll(".field-error").forEach((node) => { node.textContent = ""; });\n  }\n\n  function showErrors(errors) {\n    clearErrors();\n    const summary = byId("error-summary");\n    const list = summary.querySelector("ul");\n    errors.forEach(({ field, message }) => {\n      const input = byId(field.replaceAll("_", "-"));\n      if (!input) return;\n      input.setAttribute("aria-invalid", "true");\n      const error = byId(`${field.replaceAll("_", "-")}-error`);\n      if (error) error.textContent = message;\n      const link = make("a", message); link.href = `#${input.id}`;\n      const item = document.createElement("li"); item.append(link); list.append(item);\n    });\n    summary.hidden = false;\n    summary.focus();\n  }\n\n  function clientErrors(values) {\n    const errors = [];\n    if (!values.display_name.trim()) errors.push({ field: "display_name", message: "Enter your name." });\n    if (!values.biography.trim()) errors.push({ field: "biography", message: "Enter your biography." });\n    if (values.website) {\n      try {\n        const url = new URL(values.website);\n        if (!["http:", "https:"].includes(url.protocol)) throw new Error();\n      } catch (_) { errors.push({ field: "website", message: "Enter a complete HTTP or HTTPS website address." }); }\n    }\n    return errors;\n  }\n\n  async function load() {\n    setStatus("Checking your secure session…");\n    try {\n      const session = await api("/api/v1/session");\n      state.csrf = session.csrf_token;\n      const portal = await api("/api/v1/speaker/portal");\n      renderPortal(portal);\n      await Promise.all([loadAssets(), loadResources()]);\n      setStatus("Your speaker portal is ready.", "success");\n    } catch (error) {\n      if (error.status === 401 || error.status === 404) {\n        byId("portal").hidden = true;\n        byId("auth-state").hidden = false;\n        setStatus("Speaker access is required to view this portal.", "error");\n      } else {\n        setStatus("We couldn’t load your portal. Try again in a moment.", "error");\n      }\n    }\n  }\n\n  byId("profile-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const button = byId("save-profile");\n    const values = Object.fromEntries(new FormData(event.currentTarget));\n    values.links = values.website ? [values.website] : [];\n    delete values.website;\n    const errors = clientErrors(values);\n    if (errors.length) { showErrors(errors); return; }\n    clearErrors();\n    button.disabled = true;\n    button.textContent = "Saving…";\n    try {\n      const profile = await api("/api/v1/speaker/profile", {\n        method: "PATCH",\n        headers: {\n          "content-type": "application/json", "x-csrf-token": state.csrf,\n          "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}`\n        },\n        body: JSON.stringify({ ...values, version: state.version })\n      });\n      fillProfile(profile);\n      const portal = await api("/api/v1/speaker/portal");\n      renderPortal(portal);\n      announceOnboardingChange();\n      setStatus("Profile saved. Related onboarding tasks are up to date.", "success");\n    } catch (error) {\n      if (error.status === 409 || error.status === 412) {\n        byId("stale-warning").hidden = false;\n        byId("stale-warning").focus?.();\n        setStatus("Your profile was not saved because a newer version exists.", "error");\n      } else if (error.status === 401) {\n        byId("portal").hidden = true; byId("auth-state").hidden = false;\n        setStatus("Your session ended before the profile could be saved.", "error");\n      } else if (error.status === 422 && error.details.length) {\n        showErrors(error.details.map((detail) => ({ field: detail.field || detail.loc?.at(-1), message: detail.message || "Check this field." })));\n        setStatus("Your profile has errors. Nothing was saved.", "error");\n      } else {\n        setStatus("We couldn’t save your profile. Your entries remain on this page.", "error");\n      }\n    } finally {\n      button.disabled = false;\n      button.textContent = "Save profile";\n    }\n  });\n\n  byId("reload-profile").addEventListener("click", async () => {\n    try {\n      const portal = await api("/api/v1/speaker/portal");\n      renderPortal(portal);\n      setStatus("Latest profile loaded. Review it before saving.");\n    } catch (_) { setStatus("We couldn’t reload the latest profile.", "error"); }\n  });\n\n  byId("speaker-sign-in").addEventListener("click", () => {\n    location.assign(`/sign-in?redirect=${encodeURIComponent(location.pathname)}`);\n  });\n\n  function updateBiographyCount() {\n    const length = byId("biography").value.length;\n    byId("biography-count").textContent = `${length.toLocaleString()} of 5,000 characters`;\n  }\n  byId("biography").addEventListener("input", updateBiographyCount);\n\n  function safeUploadUrl(value) {\n    try {\n      const url = new URL(value, location.origin);\n      const trustedR2 = url.protocol === "https:" && url.hostname.endsWith(".r2.cloudflarestorage.com");\n      return url.origin === location.origin || trustedR2 ? url : null;\n    } catch (_) { return null; }\n  }\n\n  function safeUploadHeaders(headers, contentType) {\n    const safe = { "content-type": contentType };\n    Object.entries(headers || {}).forEach(([name, value]) => {\n      const lower = name.toLowerCase();\n      if (["content-type", "x-amz-checksum-sha256"].includes(lower)) safe[lower] = String(value);\n    });\n    return safe;\n  }\n\n  function uploadFile(url, method, headers, file, progress) {\n    return new Promise((resolve, reject) => {\n      if (method !== "PUT") { reject(new Error("Upload authorization used an unsupported method.")); return; }\n      const request = new XMLHttpRequest();\n      request.open("PUT", url.toString());\n      request.withCredentials = false;\n      Object.entries(headers).forEach(([name, value]) => request.setRequestHeader(name, value));\n      request.upload.addEventListener("progress", (event) => {\n        if (event.lengthComputable) progress.value = Math.round((event.loaded / event.total) * 100);\n      });\n      request.addEventListener("load", () => request.status >= 200 && request.status < 300\n        ? resolve() : reject(new Error(`Storage upload failed (${request.status}).`)));\n      request.addEventListener("error", () => reject(new Error("Storage upload could not be reached.")));\n      request.send(file);\n    });\n  }\n\n  async function checksum(file) {\n    const digest = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());\n    return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");\n  }\n\n  function validateFile(kind, file) {\n    const rule = uploadRules[kind];\n    if (!file) return "Choose a file to upload.";\n    if (!rule.types.has(file.type)) return "This file type is not allowed.";\n    if (file.size <= 0 || file.size > rule.max) return `File must be larger than zero and no more than ${Math.round(rule.max / 1024 / 1024)} MB.`;\n    return null;\n  }\n\n  function taskForKind(kind) {\n    return state.portal?.tasks?.find((task) => task.task_type === kind && task.state === "open")?.id || null;\n  }\n\n  function safeEmbedUrl(value) {\n    try {\n      const url = new URL(value);\n      const allowed = new Set(["www.youtube.com", "youtube.com", "www.youtube-nocookie.com", "player.vimeo.com", "docs.google.com", "drive.google.com", "calendar.google.com"]);\n      return url.protocol === "https:" && allowed.has(url.hostname) ? url.toString() : null;\n    } catch (_) { return null; }\n  }\n\n  async function loadResources() {\n    const container = byId("resource-list");\n    try {\n      const result = await api("/api/v1/speaker/resources");\n      byId("resource-count").textContent = String(result.data.length);\n      if (!result.data.length) {\n        container.replaceChildren(make("p", "No resources have been published yet.", "empty"));\n        return;\n      }\n      const cards = result.data.map((resource) => {\n        const details = make("details", undefined, "resource-card");\n        details.append(make("summary", resource.title));\n        if (resource.summary) details.append(make("p", resource.summary, "help"));\n        if (resource.body_text) details.append(make("p", resource.body_text, "resource-card__body"));\n        const embed = safeEmbedUrl(resource.embed_url);\n        if (embed) {\n          const frame = document.createElement("iframe");\n          frame.className = "resource-embed";\n          frame.src = embed;\n          frame.title = resource.title;\n          frame.loading = "lazy";\n          frame.referrerPolicy = "no-referrer";\n          frame.sandbox = "allow-scripts allow-same-origin allow-popups";\n          details.append(frame);\n        }\n        return details;\n      });\n      container.replaceChildren(...cards);\n    } catch (_) {\n      container.replaceChildren(make("p", "Resources could not be loaded.", "empty"));\n    }\n  }\n\n  async function loadAssets() {\n    const status = byId("asset-status");\n    try {\n      const eventId = state.portal?.event?.id;\n      if (!eventId) throw new Error("Speaker event is unavailable.");\n      const result = await api(`/api/v1/speaker/events/${encodeURIComponent(eventId)}/assets`);\n      const assets = result.data || [];\n      const list = byId("asset-list"); list.replaceChildren();\n      if (!assets.length) list.append(make("li", "No clean assets uploaded yet.", "empty"));\n      assets.forEach((asset) => {\n        const item = document.createElement("li");\n        item.append(make("strong", asset.filename), make("span", asset.state.replaceAll("_", " ")));\n        list.append(item);\n      });\n      status.textContent = `${assets.length} current clean asset${assets.length === 1 ? "" : "s"}.`;\n      status.classList.remove("error");\n    } catch (_) {\n      status.textContent = "Current assets could not be loaded. Uploads are unavailable until this reconnects.";\n      status.classList.add("error");\n    }\n  }\n\n  document.querySelectorAll(".upload-card").forEach((form) => form.addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const kind = form.dataset.kind;\n    const file = form.elements.file.files[0];\n    const status = form.querySelector(".upload-status");\n    const progress = form.querySelector("progress");\n    const button = form.querySelector("button[type=submit]");\n    const validation = validateFile(kind, file);\n    if (validation) { status.textContent = validation; status.classList.add("error"); return; }\n    button.disabled = true; progress.hidden = false; progress.value = 0;\n    status.classList.remove("error"); status.textContent = "Checking file integrity…";\n    try {\n      const eventId = state.portal?.event?.id;\n      if (!eventId) throw new Error("Speaker event is unavailable.");\n      const authorization = await api(`/api/v1/speaker/events/${encodeURIComponent(eventId)}/upload-authorizations`, {\n        method: "POST",\n        headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` },\n        body: JSON.stringify({\n          kind, submission_id: form.elements.submission_id?.value || null,\n          task_id: taskForKind(kind), filename: file.name, content_type: file.type,\n          byte_size: file.size, checksum_sha256: await checksum(file)\n        })\n      });\n      const uploadUrl = safeUploadUrl(authorization.upload_url);\n      if (!uploadUrl || authorization.expires_at_ms <= Date.now()) throw new Error("Upload authorization is invalid or expired.");\n      status.textContent = "Uploading…";\n      await uploadFile(uploadUrl, authorization.method, safeUploadHeaders(authorization.headers, file.type), file, progress);\n      status.textContent = "Upload received. Starting safety checks…";\n      const completion = await api(`/api/v1/speaker/events/${encodeURIComponent(eventId)}/upload-intents/${encodeURIComponent(authorization.intent_id)}/complete`, {\n        method: "POST", headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` }, body: "{}"\n      });\n      progress.value = 100;\n      if (completion.state === "rejected") {\n        status.textContent = "This file was rejected by the safety scan. It was not made available. Choose a different file.";\n        status.classList.add("error");\n      } else if (completion.state === "clean") {\n        status.textContent = "Upload checked and ready.";\n      } else {\n        status.textContent = "Upload complete. The file is being checked before it becomes current.";\n      }\n      form.elements.file.value = "";\n      await loadAssets();\n      const portal = await api("/api/v1/speaker/portal"); renderPortal(portal);\n      announceOnboardingChange();\n    } catch (error) {\n      status.textContent = error.message || "Upload failed. Choose the file and try again.";\n      status.classList.add("error");\n    } finally { button.disabled = false; }\n  }));\n  load();\n})();\n'

SPEAKER_CSS = '@import url("/product/assets/product.css?v=11");\n\nhtml { scroll-padding-top: 1rem; }\n.site-header { background: var(--navy); }\n.header-layout { min-height: 4.5rem; }\nmain { padding-block: 1.5rem 4rem; }\n.hero { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(17rem, .75fr); gap: 1.25rem; align-items: end; margin: 1.5rem 0; }\n.timezone, .field-meta { color: var(--muted); font-size: .9rem; }\n.progress-card { display: grid; gap: .55rem; padding: 1.25rem; border: 1px solid var(--line); border-radius: .85rem; background: white; box-shadow: var(--shadow); }\n.progress-card strong { font-size: 1.2rem; }\nprogress { width: 100%; height: .75rem; accent-color: var(--blue); }\n.portal-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.15rem; }\n.profile-panel { grid-column: 1 / -1; }\n.count-badge { display: inline-flex; align-items: center; justify-content: center; min-width: 1.8rem; min-height: 1.8rem; padding-inline: .45rem; border-radius: 99rem; background: #e4ebff; color: #2447aa; font-size: .8rem; font-weight: 800; }\n.task-link { display: inline-flex; min-height: 2.75rem; align-items: center; margin-top: .6rem; font-weight: 750; }\n.task-form { margin-top: .8rem; padding-top: .8rem; border-top: 1px solid var(--line); }\n.profile-panel .form-grid { grid-template-columns: minmax(8rem, .3fr) minmax(0, 1fr); align-items: start; }\n.profile-panel .form-grid > label { padding-top: .8rem; }\n.profile-panel .form-grid > div > input, .profile-panel .form-grid > div > textarea { margin-top: 0; }\n.field-meta { display: flex; justify-content: space-between; gap: 1rem; }\n.field-meta p { margin: .3rem 0; }\n.field-error { min-height: 1.4em; margin: .25rem 0 .65rem; color: var(--danger); font-weight: 650; }\n.error-summary, .stale-warning { margin: 1rem 0; padding: 1rem; border: 1px solid #efbdb7; border-radius: .65rem; background: #fff0ee; color: #7a271a; }\n.inline-status { margin: 1rem 0; padding: .75rem; border-left: .25rem solid var(--blue); background: #edf2ff; }\n.asset-list { display: grid; gap: .5rem; margin: 0 0 1.25rem; padding: 0; list-style: none; }\n.asset-list li { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .5rem; padding: .75rem; border: 1px solid var(--line); border-radius: .65rem; }\n.upload-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }\n.upload-card { min-width: 0; display: flex; flex-direction: column; gap: .65rem; padding: 1rem; border: 1px solid var(--line); border-radius: .75rem; background: #fbfcfe; }\n.upload-card h3, .upload-card p, .upload-card label { margin: 0; }\n.upload-card button { margin-top: auto; }\n.upload-status { min-height: 1.5em; color: var(--muted); }\n.resource-list { display: grid; gap: 1rem; margin-top: 1rem; }\n.resource-card { padding: 1rem; border: 1px solid var(--line); border-radius: .7rem; background: #fbfcfe; }\n.resource-card summary { cursor: pointer; font-weight: 800; }\n.resource-card__body { white-space: pre-wrap; }\n\n@media (max-width: 48rem) {\n  .hero, .portal-grid, .profile-panel .form-grid { grid-template-columns: 1fr; }\n  .profile-panel { grid-column: auto; }\n  .profile-panel .form-grid > label { padding: .2rem 0 0; }\n  .field-meta { display: block; }\n  .upload-grid { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }\n'

ADMIN_ONBOARDING_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light">\n  <title>Speaker onboarding · SessionBuddy</title>\n  <link rel="stylesheet" href="/admin/onboarding/assets/onboarding.css?v=2">\n  <link rel="stylesheet" href="/app-shell/assets/app-shell.css?v=3">\n  <script src="/app-shell/assets/app-shell.js?v=4" defer></script>\n  <script src="/admin/onboarding/assets/onboarding.js?v=1" defer></script>\n</head>\n<body class="app-body">\n  <a class="skip-link" href="#main">Skip to content</a>\n  <header data-auth-shell></header>\n  <main id="main" class="shell" tabindex="-1">\n    <section class="hero" aria-labelledby="page-title">\n      <div><h1 id="page-title">Speaker onboarding</h1><p id="event-name">See who is blocked and what they still owe.</p></div>\n      <div class="connection"><span id="connection-dot" aria-hidden="true"></span><strong id="connection-state">Connecting</strong><span id="last-refreshed">Not refreshed yet</span></div>\n    </section>\n    <div id="status" class="status" role="status" aria-live="polite">Checking your admin session…</div>\n    <section class="summary-grid" aria-label="Onboarding summary">\n      <article><span>Complete</span><strong id="count-complete">—</strong></article>\n      <article><span>Incomplete</span><strong id="count-incomplete">—</strong></article>\n      <article><span>Overdue</span><strong id="count-overdue">—</strong></article>\n      <article><span>Due soon</span><strong id="count-due-soon">—</strong></article>\n    </section>\n    <section class="panel" aria-labelledby="filters-title">\n      <div class="section-heading"><h2 id="filters-title">Filters</h2><button id="refresh" class="secondary" type="button">Refresh</button></div>\n      <form id="filters" class="filters">\n        <label for="state">Task state<select id="state" name="state"><option value="">All tasks</option><option value="open">All outstanding</option><option value="completed">Completed</option><option value="overdue">Overdue outstanding</option><option value="due_soon">Due-soon outstanding</option></select></label>\n        <label for="task-type">Task type<select id="task-type" name="task_type"><option value="">All task types</option><option value="biography">Biography</option><option value="profile">Profile</option><option value="headshot">Headshot</option><option value="slides">Slides</option><option value="supporting_document">Supporting document</option></select></label>\n        <div class="filter-actions"><button type="submit">Apply filters</button><button id="clear-filters" class="secondary" type="button">Clear</button></div>\n      </form>\n    </section>\n    <section class="panel" aria-labelledby="list-title" aria-busy="true" id="results-panel">\n      <div class="section-heading"><h2 id="list-title">Speakers needing attention</h2><span id="result-count" class="count">—</span></div>\n      <div class="desktop-table"><table><thead><tr><th scope="col">Speaker</th><th scope="col">Session</th><th scope="col">Missing task</th><th scope="col">Due</th><th scope="col">Last activity</th><th scope="col">Action</th></tr></thead><tbody id="onboarding-rows"><tr><td colspan="6">Loading…</td></tr></tbody></table></div>\n      <ul id="onboarding-cards" class="mobile-cards" aria-label="Onboarding results"><li>Loading…</li></ul>\n      <div id="empty" class="empty" hidden><strong>No speakers match this view.</strong><p>Try clearing a filter, or check again after new onboarding activity.</p></div>\n      <div class="pagination"><button id="load-more" class="secondary" type="button" hidden>Load more</button></div>\n    </section>\n  </main>\n</body>\n</html>\n'

ADMIN_ONBOARDING_JS = '(() => {\n  "use strict";\n  const REFRESH_MS = 5000;\n  const ALLOWED_STATES = new Set(["", "open", "completed", "overdue", "due_soon"]);\n  const ALLOWED_TASK_TYPES = new Set(["", "biography", "profile", "headshot", "slides", "supporting_document"]);\n  const routeMatch = location.pathname.match(/^\\/admin\\/events\\/([^/]+)\\/onboarding$/);\n  let eventId = "";\n  try { eventId = routeMatch ? decodeURIComponent(routeMatch[1]) : ""; } catch (_) { eventId = ""; }\n  if (!/^[A-Za-z0-9_.-]{1,128}$/.test(eventId)) eventId = "";\n  const state = { timer: null, loading: false, cursor: null, rows: [], lastSuccess: null, timeZone: "UTC", csrf: "", channel: null };\n  const byId = (id) => document.getElementById(id);\n  const make = (tag, value, className) => { const node = document.createElement(tag); if (value !== undefined) node.textContent = value; if (className) node.className = className; return node; };\n\n  function setStatus(message, error = false) {\n    byId("status").textContent = message;\n    byId("status").classList.toggle("error", error);\n  }\n\n  function setConnection(kind, label) {\n    byId("connection-dot").className = kind;\n    byId("connection-state").textContent = label;\n    byId("last-refreshed").textContent = state.lastSuccess\n      ? `Last refreshed ${state.lastSuccess.toLocaleTimeString()}` : "Not refreshed yet";\n  }\n\n  function recordTelemetry(started, response) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = innerWidth;\n    window.__sessionbuddyTelemetryDraft = {\n      schema_version: 1, page_template: "/admin/events/{event_id}/onboarding",\n      navigation_type: navigation?.type || "unknown",\n      device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop",\n      sampled: false, lcp_ms: null, inp_ms: null, cls: null,\n      ttfb_ms: navigation?.responseStart ?? null, fcp_ms: null, route_transition_ms: null,\n      critical_api_ms: Math.max(0, performance.now() - started),\n      api_request_id: response.headers.get("x-request-id")\n    };\n  }\n\n  async function api(path, options = {}) {\n    const started = performance.now();\n    const response = await fetch(path, { ...options, credentials: "same-origin", headers: { accept: "application/json", ...(options.headers || {}) } });\n    recordTelemetry(started, response);\n    let body = null;\n    try { body = await response.json(); } catch (_) { body = null; }\n    if (!response.ok) {\n      const error = new Error(body?.error?.message || `Request failed (${response.status})`);\n      error.status = response.status; throw error;\n    }\n    return body;\n  }\n\n  function selectedFilters() {\n    const selectedState = byId("state").value;\n    const taskType = byId("task-type").value;\n    return {\n      state: ALLOWED_STATES.has(selectedState) ? selectedState : "",\n      task_type: ALLOWED_TASK_TYPES.has(taskType) ? taskType : ""\n    };\n  }\n\n  function query(cursor = null) {\n    const params = new URLSearchParams();\n    const filters = selectedFilters();\n    if (filters.state) params.set("state", filters.state);\n    if (filters.task_type) params.set("task_type", filters.task_type);\n    if (cursor) params.set("cursor", cursor);\n    return params.toString();\n  }\n\n  function preserveFilters() {\n    const params = new URLSearchParams();\n    const filters = selectedFilters();\n    if (filters.state) params.set("state", filters.state);\n    if (filters.task_type) params.set("task_type", filters.task_type);\n    history.replaceState(null, "", `${location.pathname}${params.size ? `?${params}` : ""}`);\n  }\n\n  function formatDate(value) {\n    if (value === null || value === undefined) return "No due date";\n    try {\n      return new Intl.DateTimeFormat(undefined, {\n        dateStyle: "medium", timeStyle: "short", timeZone: state.timeZone\n      }).format(new Date(value));\n    } catch (_) { return "Date unavailable"; }\n  }\n\n  function isOverdue(row) { return row.state === "overdue"; }\n\n  function addTableRow(row) {\n    const tr = document.createElement("tr");\n    const speaker = document.createElement("td");\n    const link = make("a", row.display_name); link.href = speakerLink(row); speaker.append(link);\n    tr.append(speaker);\n    [row.proposal_title, row.task_title, formatDate(row.due_at_ms), formatDate(row.last_activity_at_ms)].forEach((value, index) => {\n      const td = make("td", value, index === 1 ? "task-name" : index === 2 && isOverdue(row) ? "overdue" : ""); tr.append(td);\n    });\n    const action = document.createElement("td");\n    const button = make("button", "Send reminder", "compact secondary"); button.type = "button";\n    button.addEventListener("click", () => sendReminder(row, button)); action.append(button); tr.append(action);\n    byId("onboarding-rows").append(tr);\n  }\n\n  function addCard(row) {\n    const item = document.createElement("li");\n    const heading = document.createElement("h3");\n    const speaker = make("a", row.display_name); speaker.href = speakerLink(row); heading.append(speaker); item.append(heading);\n    const list = document.createElement("dl");\n    [["Session", row.proposal_title], ["Missing", row.task_title], ["Due", formatDate(row.due_at_ms)], ["Last activity", formatDate(row.last_activity_at_ms)]].forEach(([label, value]) => {\n      list.append(make("dt", label), make("dd", value, label === "Due" && isOverdue(row) ? "overdue" : ""));\n    });\n    const reminder = make("button", "Send reminder", "compact secondary"); reminder.type = "button";\n    reminder.addEventListener("click", () => sendReminder(row, reminder));\n    item.append(list, reminder); byId("onboarding-cards").append(item);\n  }\n\n  function speakerLink(row) {\n    return `/admin/events/${encodeURIComponent(eventId)}/speakers/${encodeURIComponent(row.event_speaker_id)}`;\n  }\n\n  async function sendReminder(row, button) {\n    button.disabled = true;\n    try {\n      await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/speaker-tasks/${encodeURIComponent(row.task_id)}/reminders`, {\n        method: "POST",\n        headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` },\n        body: "{}"\n      });\n      setStatus(`Reminder queued for ${row.display_name}.`);\n    } catch (error) {\n      setStatus(error.status === 404\n        ? "Reminder delivery is not connected in this environment yet. No message was sent."\n        : "The reminder could not be queued. No message was sent.", true);\n    } finally { button.disabled = false; }\n  }\n\n  function render(data, append) {\n    const summary = data.summary;\n    state.timeZone = data.time_zone;\n    byId("event-name").textContent = `${data.event_name} · Dates shown in ${data.time_zone}`;\n    byId("count-complete").textContent = summary.complete;\n    byId("count-incomplete").textContent = summary.incomplete;\n    byId("count-overdue").textContent = summary.overdue;\n    byId("count-due-soon").textContent = summary.due_soon;\n    const incoming = data.data;\n    if (!append) {\n      state.rows = [];\n      byId("onboarding-rows").replaceChildren();\n      byId("onboarding-cards").replaceChildren();\n    }\n    state.rows.push(...incoming);\n    incoming.forEach((row) => { addTableRow(row); addCard(row); });\n    byId("result-count").textContent = String(state.rows.length);\n    byId("empty").hidden = state.rows.length !== 0;\n    byId("load-more").hidden = !data.next_cursor;\n    state.cursor = data.next_cursor || null;\n  }\n\n  async function refresh({ append = false, announce = false } = {}) {\n    if (state.loading || document.hidden) return;\n    state.loading = true;\n    byId("results-panel").setAttribute("aria-busy", "true");\n    setConnection("", state.lastSuccess ? "Refreshing" : "Connecting");\n    try {\n      const filterQuery = query(append ? state.cursor : null);\n      const endpoint = `/api/v1/admin/events/${encodeURIComponent(eventId)}/onboarding`;\n      const data = await api(`${endpoint}${filterQuery ? `?${filterQuery}` : ""}`);\n      render(data, append);\n      state.lastSuccess = new Date(data.generated_at_ms);\n      setConnection("live", "Live snapshot");\n      setStatus(announce ? "Onboarding snapshot refreshed." : `${state.rows.length} speaker record${state.rows.length === 1 ? "" : "s"} shown.`);\n    } catch (error) {\n      const authMessage = error.status === 401 || error.status === 403\n        ? "Your account cannot access this event."\n        : "Live refresh failed. Showing the last successful snapshot while reconnecting.";\n      setStatus(authMessage, true);\n      setConnection("stale", error.status === 401 || error.status === 403 ? "Access unavailable" : "Reconnecting");\n    } finally {\n      state.loading = false;\n      byId("results-panel").setAttribute("aria-busy", "false");\n    }\n  }\n\n  function startPolling() {\n    clearInterval(state.timer);\n    if (!document.hidden) state.timer = setInterval(() => refresh(), REFRESH_MS);\n  }\n\n  function connectInvalidations() {\n    if (!("BroadcastChannel" in window)) return;\n    state.channel?.close();\n    state.channel = new BroadcastChannel(`sessionbuddy:onboarding:${eventId}`);\n    state.channel.addEventListener("message", () => refresh());\n  }\n\n  function initializeFilters() {\n    const params = new URLSearchParams(location.search);\n    const selectedState = params.get("state") || "";\n    const taskType = params.get("task_type") || "";\n    byId("state").value = ALLOWED_STATES.has(selectedState) ? selectedState : "";\n    byId("task-type").value = ALLOWED_TASK_TYPES.has(taskType) ? taskType : "";\n    preserveFilters();\n  }\n\n  byId("filters").addEventListener("submit", (event) => { event.preventDefault(); preserveFilters(); refresh({ announce: true }); });\n  byId("clear-filters").addEventListener("click", () => { byId("filters").reset(); preserveFilters(); refresh({ announce: true }); });\n  byId("refresh").addEventListener("click", () => refresh({ announce: true }));\n  byId("load-more").addEventListener("click", () => refresh({ append: true, announce: true }));\n  document.addEventListener("visibilitychange", () => {\n    startPolling();\n    if (document.hidden) setConnection("", "Updates paused");\n    else refresh({ announce: true });\n  });\n  window.addEventListener("online", () => refresh({ announce: true }));\n  window.addEventListener("offline", () => setConnection("stale", "Offline · snapshot retained"));\n  window.addEventListener("pageshow", (event) => { if (event.persisted) refresh({ announce: true }); });\n  window.addEventListener("sessionbuddy:onboarding-invalidated", () => refresh());\n\n  async function initialize() {\n    if (!eventId) {\n      setStatus("This onboarding link is invalid. Return to Programs and choose an event.", true);\n      setConnection("stale", "Invalid event link");\n      return;\n    }\n    initializeFilters();\n    try {\n      const session = await api("/api/v1/session");\n      state.csrf = session.csrf_token;\n      await refresh();\n      connectInvalidations();\n      startPolling();\n    } catch (error) {\n      setStatus(error.status === 401 ? "Sign in as an event administrator to continue." : "We couldn’t verify your admin session.", true);\n      setConnection("stale", "Access unavailable");\n    }\n  }\n  initialize();\n})();\n'

ADMIN_ONBOARDING_CSS = ':root { color-scheme: light; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; color: #182230; background: #f7f8fa; }\n* { box-sizing: border-box; }\nbody { margin: 0; line-height: 1.5; }\n.shell { width: min(72rem, calc(100% - 2rem)); margin-inline: auto; }\n.skip-link { position: fixed; top: -5rem; left: 1rem; z-index: 10; padding: .7rem 1rem; background: white; color: #173f9f; }\n.skip-link:focus { top: .5rem; }\n.site-header { background: #172033; color: white; }\n.header-layout { min-height: 4.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem; }\n.brand { color: white; font-weight: 800; text-decoration: none; }\nnav { display: flex; flex-wrap: wrap; gap: .2rem; }\nnav a { min-height: 2.75rem; display: inline-flex; align-items: center; padding: .5rem .75rem; border-radius: .5rem; color: #e8edff; text-decoration: none; }\nnav a[aria-current="page"] { background: #34425e; color: white; }\nmain { padding-block: 2rem 4rem; }\n.hero { display: flex; justify-content: space-between; align-items: end; gap: 1.5rem; }\n.eyebrow { margin: 0 0 .25rem; color: #63708a; font-size: .78rem; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }\nh1, h2 { margin: .15rem 0 .5rem; line-height: 1.15; }\nh1 { font-size: clamp(1.9rem, 4vw, 2.6rem); }\n.connection { min-width: 13rem; display: grid; grid-template-columns: auto 1fr; gap: .1rem .55rem; align-items: center; padding: .8rem 1rem; border: 1px solid #d8deea; border-radius: .75rem; background: white; }\n.connection span:last-child { grid-column: 2; color: #5c687d; font-size: .85rem; }\n#connection-dot { width: .65rem; height: .65rem; border-radius: 50%; background: #d28619; }\n#connection-dot.live { background: #168253; }\n#connection-dot.stale { background: #b42318; }\n.status { margin: 1.25rem 0; padding: .75rem .85rem; border: 1px solid #bfdbfe; border-radius: .5rem; background: #eff6ff; }\n.status.error { border-color: #b42318; background: #fff0ee; color: #7a271a; }\n.summary-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; }\n.summary-grid article, .panel { border: 1px solid #e4e7ec; border-radius: .7rem; background: white; box-shadow: 0 1px 2px rgb(16 24 40 / 4%); }\n.summary-grid article { display: grid; gap: .2rem; padding: 1rem; }\n.summary-grid span { color: #5c687d; }\n.summary-grid strong { font-size: 1.8rem; }\n.panel { margin-top: 1.25rem; padding: 1.25rem; }\n.section-heading { display: flex; justify-content: space-between; align-items: start; gap: 1rem; }\n.filters { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)) auto; gap: 1rem; align-items: end; }\nlabel { display: grid; gap: .35rem; font-weight: 700; }\nselect { width: 100%; min-height: 2.75rem; padding: .65rem .75rem; border: 1px solid #aeb8ca; border-radius: .55rem; background: white; color: inherit; font: inherit; }\nbutton { min-height: 2.75rem; padding: .65rem 1rem; border: 0; border-radius: .5rem; background: #2563eb; color: white; font: inherit; font-weight: 650; cursor: pointer; }\nbutton.secondary { border: 1px solid #aeb8ca; background: white; color: #263550; }\nbutton.compact { min-height: 2.75rem; padding: .45rem .7rem; white-space: nowrap; }\nbutton:disabled { cursor: wait; opacity: .55; }\n.filter-actions { display: flex; gap: .5rem; }\n.count { min-width: 2rem; padding: .2rem .6rem; border-radius: 999px; background: #e9eeff; color: #274aa9; text-align: center; font-weight: 750; }\n.desktop-table { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { padding: .8rem; border-bottom: 1px solid #dce1eb; text-align: left; vertical-align: top; }\nth { color: #536079; font-size: .78rem; text-transform: uppercase; }\n.task-name { font-weight: 750; }\n.overdue { color: #9b241a; font-weight: 750; }\n.mobile-cards { display: none; margin: 0; padding: 0; list-style: none; }\n.mobile-cards li { padding: 1rem 0; border-bottom: 1px solid #dce1eb; }\n.mobile-cards h3 { margin: 0; }\n.mobile-cards dl { display: grid; grid-template-columns: 7rem 1fr; gap: .4rem; }\n.mobile-cards dt { color: #5c687d; }\n.mobile-cards dd { margin: 0; }\n.empty { margin-top: .8rem; padding: 1rem; border-radius: .7rem; background: #f1f4fa; }\n.empty p { margin-bottom: 0; }\n.pagination { display: flex; justify-content: center; margin-top: 1rem; }\n:where(a, button, select):focus-visible { outline: 3px solid #2563eb; outline-offset: 3px; }\n[hidden] { display: none !important; }\n@media (max-width: 48rem) {\n  .header-layout, .hero { align-items: flex-start; flex-direction: column; }\n  .header-layout { padding-block: .8rem; }\n  nav { width: 100%; overflow-x: auto; flex-wrap: nowrap; }\n  .connection { width: 100%; }\n  .summary-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .filters { grid-template-columns: 1fr; }\n  .filter-actions, .filter-actions button, #refresh { width: 100%; }\n  .desktop-table { display: none; }\n  .mobile-cards { display: block; }\n}\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }\n'

AGENDA_ADMIN_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agenda editor · SessionBuddy</title><link rel="stylesheet" href="/product/assets/product.css?v=11"><link rel="stylesheet" href="/admin/agenda/assets/agenda.css?v=1"><link rel="stylesheet" href="/app-shell/assets/app-shell.css?v=3"><script src="/app-shell/assets/app-shell.js?v=4" defer></script><script src="/admin/agenda/assets/agenda.js?v=1" defer></script></head>\n<body class="app-body"><a class="skip-link" href="#main">Skip to content</a><header data-auth-shell></header>\n<main id="main" class="shell" tabindex="-1"><section class="agenda-hero"><div><h1 id="event-title">Agenda</h1><p id="timezone" class="lede">Loading schedule…</p></div><div class="revision"><span>Draft revision</span><strong id="revision">—</strong></div></section><div id="status" class="status" role="status" aria-live="polite">Checking your session…</div>\n<section class="agenda-toolbar" aria-labelledby="view-title"><div><h2 id="view-title">View</h2></div><fieldset><legend class="sr-only">Agenda view</legend><div class="segmented"><label><input type="radio" name="view" value="list" checked><span>List</span></label><label><input type="radio" name="view" value="day"><span>Day</span></label><label><input type="radio" name="view" value="week"><span>Week</span></label><label><input type="radio" name="view" value="track"><span>Track</span></label><label><input type="radio" name="view" value="room"><span>Room</span></label></div></fieldset><button id="refresh" class="secondary" type="button">Refresh</button><button id="publish" type="button">Publish agenda</button></section>\n<div class="agenda-layout"><aside class="panel" aria-labelledby="unscheduled-title"><h2 id="unscheduled-title">Unscheduled sessions</h2><p class="help">Drag a session into a group, or select Edit to schedule it with the keyboard form.</p><ul id="unscheduled" class="session-list"><li>Loading…</li></ul></aside><section id="agenda" class="panel board-panel" aria-labelledby="agenda-title" aria-busy="true"><div class="section-heading"><h2 id="agenda-title">Draft schedule</h2><span id="item-count" class="count">—</span></div><div id="conflict-banner" class="conflict" role="alert" tabindex="-1" hidden><strong>That change conflicts with the schedule.</strong><ul></ul></div><div id="board" class="agenda-board"></div><div id="empty" class="empty" hidden><strong>No sessions are scheduled.</strong><p>Add an accepted session from the unscheduled list.</p></div></section></div>\n<dialog id="editor" aria-labelledby="editor-title"><form id="editor-form"><div class="dialog-heading"><div><p class="eyebrow">Keyboard editor</p><h2 id="editor-title">Schedule session</h2></div><button id="close-editor" class="icon-button secondary" type="button" aria-label="Close schedule editor">×</button></div><div id="editor-errors" class="conflict" role="alert" tabindex="-1" hidden><strong>Review this schedule change.</strong><ul></ul></div><input name="item_id" type="hidden"><input name="session_id" type="hidden"><input name="version" type="hidden"><label>Session<input name="title" readonly></label><div class="form-grid"><label>Starts<input name="start_at" type="datetime-local" required></label><label>Ends<input name="end_at" type="datetime-local" required></label><label>Room<select name="room_id" required></select></label><label>Track<select name="track_id"><option value="">No track</option></select></label></div><p id="preview-state" class="preview-state" role="status" aria-live="polite">Change a field to check conflicts.</p><div class="actions"><button id="cancel-editor" class="secondary" type="button">Cancel</button><button id="save-item" type="submit">Save to draft</button></div></form></dialog></main></body></html>\n'

AGENDA_JS = '(() => {\n  "use strict";\n  const match = location.pathname.match(/^\\/admin\\/events\\/([^/]+)\\/agenda$/);\n  let eventId = "";\n  try { eventId = match ? decodeURIComponent(match[1]) : ""; } catch (_) { eventId = ""; }\n  if (!/^[A-Za-z0-9_.-]{1,128}$/.test(eventId)) eventId = "";\n  const state = { csrf: "", model: null, selected: null, previewTimer: null, previewToken: 0 };\n  const byId = (id) => document.getElementById(id);\n  const make = (tag, value, className) => { const node = document.createElement(tag); if (value !== undefined) node.textContent = value; if (className) node.className = className; return node; };\n  const key = () => `${crypto.randomUUID()}-${crypto.randomUUID()}`;\n\n  async function api(path, options = {}) {\n    const response = await fetch(path, { ...options, credentials: "same-origin", headers: { accept: "application/json", ...(options.headers || {}) } });\n    let body = null; try { body = await response.json(); } catch (_) { body = null; }\n    if (!response.ok) { const error = new Error(body?.error?.message || `Request failed (${response.status})`); error.status = response.status; error.body = body; throw error; }\n    return body;\n  }\n  function status(message, error = false) { byId("status").textContent = message; byId("status").classList.toggle("error", error); }\n  function format(value, options = {}) { try { return new Intl.DateTimeFormat(undefined, { timeZone: state.model.event.time_zone, ...options }).format(new Date(value)); } catch (_) { return "Date unavailable"; } }\n  function localInput(value) { const date = new Date(value); const shifted = new Date(date.getTime() - date.getTimezoneOffset() * 60000); return shifted.toISOString().slice(0, 16); }\n  function inputMillis(value) { return new Date(value).getTime(); }\n  function eventDate(value) { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: state.model.event.time_zone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date(value)); const fields = Object.fromEntries(parts.map((part) => [part.type, part.value])); return `${fields.year}-${fields.month}-${fields.day}`; }\n  function currentView() { return document.querySelector(\'input[name="view"]:checked\').value; }\n  function groupKey(item, view) {\n    if (view === "room") return item.room_name || "Unassigned room";\n    if (view === "track") return item.track_name || "No track";\n    if (view === "day") return format(item.start_at_ms, { weekday: "long", month: "short", day: "numeric" });\n    if (view === "week") {\n      const date = new Date(item.start_at_ms);\n      date.setUTCDate(date.getUTCDate() - date.getUTCDay());\n      return `Week of ${format(date.getTime(), { month: "short", day: "numeric", year: "numeric" })}`;\n    }\n    return "All sessions";\n  }\n  function card(item, scheduled = true) {\n    const node = make("li", undefined, "session-card"); node.dataset.itemId = item.id || ""; node.dataset.sessionId = item.session_id; node.draggable = true;\n    if (item.id?.startsWith("optimistic-")) node.classList.add("optimistic");\n    node.setAttribute("aria-label", `${item.title}. ${scheduled ? "Scheduled session; drag to move or use Edit." : "Unscheduled session; drag to schedule or use Edit."}`);\n    node.append(make("h3", item.title));\n    if (scheduled) node.append(make("p", `${format(item.start_at_ms, { hour: "numeric", minute: "2-digit" })}–${format(item.end_at_ms, { hour: "numeric", minute: "2-digit" })} · ${item.room_name}`, "scheduled-meta"));\n    const edit = make("button", scheduled ? "Edit" : "Schedule", "secondary"); edit.type = "button"; edit.addEventListener("click", () => openEditor(item)); node.append(edit);\n    node.addEventListener("dragstart", (event) => { state.selected = item; node.classList.add("dragging"); event.dataTransfer.effectAllowed = "move"; event.dataTransfer.setData("text/plain", item.id || item.session_id); });\n    node.addEventListener("dragend", () => { node.classList.remove("dragging"); document.querySelectorAll(".agenda-group").forEach((group) => group.classList.remove("preview-ok", "preview-conflict")); });\n    return node;\n  }\n  function render() {\n    const model = state.model; const view = currentView();\n    byId("event-title").textContent = model.event.name; byId("timezone").textContent = `Draft agenda · ${model.event.time_zone}`;\n    byId("revision").textContent = `v${model.revision.version} · ${model.revision.state}`;\n    byId("published-link").href = `/events/${encodeURIComponent(eventId)}/schedule`;\n    byId("item-count").textContent = String(model.items.length);\n    const unscheduled = byId("unscheduled"); unscheduled.replaceChildren();\n    if (!model.unscheduled_sessions.length) unscheduled.append(make("li", "All accepted sessions are scheduled.", "empty"));\n    model.unscheduled_sessions.forEach((item) => unscheduled.append(card(item, false)));\n    const groups = new Map(); model.items.forEach((item) => { const name = groupKey(item, view); if (!groups.has(name)) groups.set(name, []); groups.get(name).push(item); });\n    const board = byId("board"); board.replaceChildren(); byId("empty").hidden = model.items.length !== 0;\n    [...groups].sort(([left], [right]) => left.localeCompare(right)).forEach(([name, items]) => {\n      const section = make("section", undefined, "agenda-group"); section.dataset.group = name; section.tabIndex = 0; section.setAttribute("aria-label", `${name} drop target`);\n      section.append(make("h3", name)); const list = make("ul", undefined, "agenda-group-list");\n      items.sort((a, b) => a.start_at_ms - b.start_at_ms).forEach((item) => list.append(card(item))); section.append(list);\n      section.addEventListener("dragover", (event) => { event.preventDefault(); event.dataTransfer.dropEffect = "move"; });\n      section.addEventListener("dragenter", () => previewDrop(section, name, view));\n      section.addEventListener("drop", (event) => { event.preventDefault(); commitDrop(section, name, view); }); board.append(section);\n    });\n    byId("agenda").setAttribute("aria-busy", "false");\n  }\n  function candidateForGroup(item, name, view) {\n    const candidate = { item_id: item.id || null, session_id: item.session_id, start_at_ms: item.start_at_ms, end_at_ms: item.end_at_ms, room_id: item.room_id || state.model.rooms[0]?.id, track_id: item.track_id || null, version: item.version || 0, event_date: eventDate(item.start_at_ms) };\n    if (view === "room") candidate.room_id = state.model.rooms.find((room) => room.name === name)?.id || candidate.room_id;\n    if (view === "track") candidate.track_id = state.model.tracks.find((track) => track.name === name)?.id || null;\n    return candidate;\n  }\n  async function preview(candidate) { return api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda/preview`, { method: "POST", headers: { "content-type": "application/json", "x-csrf-token": state.csrf }, body: JSON.stringify(candidate) }); }\n  async function previewDrop(section, name, view) {\n    if (!state.selected?.start_at_ms) return;\n    try { const result = await preview(candidateForGroup(state.selected, name, view)); section.classList.toggle("preview-ok", result.valid); section.classList.toggle("preview-conflict", !result.valid); showConflicts(result.conflicts || []); } catch (_) { section.classList.add("preview-conflict"); }\n  }\n  async function commitDrop(section, name, view) {\n    if (!state.selected?.start_at_ms) { openEditor(state.selected); return; }\n    const candidate = candidateForGroup(state.selected, name, view); const before = structuredClone(state.model);\n    try { const check = await preview(candidate); if (!check.valid) { showConflicts(check.conflicts); section.classList.add("preview-conflict"); return; } optimistic(candidate); render(); await save(candidate); status("Agenda change saved."); }\n    catch (error) { state.model = before; render(); const restored = document.querySelector(`[data-item-id="${CSS.escape(candidate.item_id || "")}"]`); restored?.classList.add("rollback"); status(error.status === 409 ? "Schedule changed elsewhere or conflicts. Your move was rolled back." : "The move could not be saved and was rolled back.", true); }\n  }\n  function optimistic(candidate) { let item = state.model.items.find((value) => value.id === candidate.item_id); if (!item) { item = { ...state.selected, id: `optimistic-${candidate.session_id}`, version: 0 }; state.model.items.push(item); state.model.unscheduled_sessions = state.model.unscheduled_sessions.filter((value) => value.session_id !== candidate.session_id); } Object.assign(item, candidate); item.room_name = state.model.rooms.find((room) => room.id === candidate.room_id)?.name || item.room_name; item.track_name = state.model.tracks.find((track) => track.id === candidate.track_id)?.name || null; }\n  async function save(candidate) { const creating = !candidate.item_id; const path = creating ? `/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda/items` : `/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda/items/${encodeURIComponent(candidate.item_id)}`; const saved = await api(path, { method: creating ? "POST" : "PATCH", headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": key() }, body: JSON.stringify(candidate) }); await load(false); return saved; }\n  function options(select, values, selected, empty) { select.replaceChildren(); if (empty) select.add(new Option(empty, "")); values.forEach((value) => select.add(new Option(value.name, value.id))); select.value = selected || ""; }\n  function openEditor(item) { if (!item) return; state.selected = item; const form = byId("editor-form"); form.elements.item_id.value = item.id || ""; form.elements.session_id.value = item.session_id; form.elements.version.value = item.version || 0; form.elements.title.value = item.title; form.elements.start_at.value = item.start_at_ms ? localInput(item.start_at_ms) : ""; form.elements.end_at.value = item.end_at_ms ? localInput(item.end_at_ms) : ""; options(form.elements.room_id, state.model.rooms, item.room_id, "Choose room"); options(form.elements.track_id, state.model.tracks, item.track_id, "No track"); clearConflicts(); byId("preview-state").textContent = "Change a field to check conflicts."; byId("editor").showModal(); }\n  function formCandidate() { const form = byId("editor-form"); const start = inputMillis(form.elements.start_at.value); return { item_id: form.elements.item_id.value || null, session_id: form.elements.session_id.value, start_at_ms: start, end_at_ms: inputMillis(form.elements.end_at.value), room_id: form.elements.room_id.value, track_id: form.elements.track_id.value || null, version: Number(form.elements.version.value), event_date: eventDate(start) }; }\n  function clearConflicts() { byId("conflict-banner").hidden = true; byId("editor-errors").hidden = true; }\n  function showConflicts(conflicts, editor = false) { const panel = byId(editor ? "editor-errors" : "conflict-banner"); const list = panel.querySelector("ul"); list.replaceChildren(); conflicts.forEach((conflict) => list.append(make("li", conflict.message))); panel.hidden = conflicts.length === 0; if (conflicts.length) panel.focus(); }\n  function schedulePreview() { clearTimeout(state.previewTimer); const token = ++state.previewToken; state.previewTimer = setTimeout(async () => { const candidate = formCandidate(); if (!Number.isFinite(candidate.start_at_ms) || !Number.isFinite(candidate.end_at_ms) || candidate.start_at_ms >= candidate.end_at_ms || !candidate.room_id) { byId("preview-state").textContent = "Enter a valid start, end, and room."; byId("preview-state").className = "preview-state error"; return; } try { const result = await preview(candidate); if (token !== state.previewToken) return; showConflicts(result.conflicts || [], true); byId("preview-state").textContent = result.valid ? "No room or speaker conflicts found." : "Conflict found. Adjust the schedule before saving."; byId("preview-state").className = `preview-state ${result.valid ? "ok" : "error"}`; byId("save-item").disabled = !result.valid; } catch (_) { byId("preview-state").textContent = "Conflict preview unavailable. Saving is disabled."; byId("preview-state").className = "preview-state error"; byId("save-item").disabled = true; } }, 150); }\n  async function load(announce = true) { const model = await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda`); state.model = model; render(); if (announce) status("Draft agenda loaded."); }\n  document.querySelectorAll(\'input[name="view"]\').forEach((input) => input.addEventListener("change", render));\n  byId("refresh").addEventListener("click", () => load().catch(() => status("Agenda could not be refreshed.", true)));\n  byId("publish").addEventListener("click", async () => {\n    const button = byId("publish"); button.disabled = true;\n    try {\n      await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda/publish`, {\n        method: "POST", headers: { "content-type": "application/json", "x-csrf-token": state.csrf },\n        body: JSON.stringify({ revision_id: state.model.revision.id, version: state.model.revision.version })\n      });\n      await load(false); status("Agenda published. Calendar updates were queued for speakers.");\n    } catch (error) { status(error.status === 409 ? "This draft changed before publication. Refresh and review it again." : "The agenda could not be published.", true); }\n    finally { button.disabled = false; }\n  });\n  byId("editor-form").addEventListener("input", schedulePreview);\n  byId("editor-form").addEventListener("submit", async (event) => { event.preventDefault(); const candidate = formCandidate(); const before = structuredClone(state.model); byId("save-item").disabled = true; try { const check = await preview(candidate); if (!check.valid) { showConflicts(check.conflicts, true); return; } optimistic(candidate); byId("editor").close(); render(); await save(candidate); status("Session scheduled successfully."); } catch (error) { state.model = before; render(); status(error.status === 409 ? "The schedule changed or conflicts. Your edit was rolled back." : "The edit could not be saved and was rolled back.", true); } finally { byId("save-item").disabled = false; } });\n  ["close-editor", "cancel-editor"].forEach((id) => byId(id).addEventListener("click", () => byId("editor").close()));\n  async function initialize() { if (!eventId) { status("Invalid agenda link. Return to Events and select an event.", true); return; } try { const session = await api("/api/v1/session"); state.csrf = session.csrf_token; await load(); } catch (error) { status(error.status === 401 ? "Sign in as an event administrator to edit this agenda." : error.status === 404 ? "No agenda has been created for this event yet." : "Agenda unavailable. Try again.", true); byId("agenda").setAttribute("aria-busy", "false"); } }\n  initialize();\n})();\n'

AGENDA_CSS = '.skip-link { position: fixed; top: -5rem; left: 1rem; z-index: 20; padding: .7rem 1rem; background: white; color: #173f9f; }.skip-link:focus{top:.5rem}.agenda-header{display:flex;justify-content:space-between;align-items:center}.agenda-header nav{display:flex;gap:.2rem}.agenda-header nav a{min-height:2.75rem;display:inline-flex;align-items:center;padding:.4rem .7rem;border-radius:.5rem;text-decoration:none}.agenda-header nav a[aria-current=page]{background:#34425e}.agenda-hero{display:flex;justify-content:space-between;align-items:end;gap:1rem;margin-bottom:1.25rem}.revision{display:grid;min-width:10rem;padding:1rem;border:1px solid #dce1eb;border-radius:.75rem;background:white}.revision span,.help{color:#59667c}.revision strong{font-size:1.25rem}.agenda-toolbar{display:flex;align-items:end;justify-content:space-between;gap:1rem;padding:1rem;border:1px solid #dce1eb;border-radius:.8rem;background:white}.agenda-toolbar h2{margin:.1rem 0}.agenda-toolbar fieldset{margin:0;padding:0;border:0}.segmented{display:flex;flex-wrap:wrap;gap:.25rem}.segmented label{margin:0}.segmented input{position:absolute;opacity:0;pointer-events:none}.segmented span{min-height:2.75rem;display:inline-flex;align-items:center;padding:.55rem .8rem;border:1px solid #aeb8ca;border-radius:.5rem;cursor:pointer}.segmented input:checked+span{border-color:#3159d9;background:#e9eeff;color:#274aa9;font-weight:750}.segmented input:focus-visible+span{outline:3px solid #e69b00;outline-offset:3px}.agenda-layout{display:grid;grid-template-columns:minmax(15rem,.35fr) minmax(0,1fr);gap:1.25rem;margin-top:1.25rem}.panel{padding:1.25rem;border:1px solid #dce1eb;border-radius:.9rem;background:white}.section-heading{display:flex;justify-content:space-between;gap:1rem;align-items:start}.count{height:max-content;padding:.2rem .6rem;border-radius:999px;background:#e9eeff;color:#274aa9;font-weight:750}.session-list{display:grid;gap:.65rem;margin:0;padding:0;list-style:none}.session-card{padding:.85rem;border:1px solid #dce1eb;border-radius:.65rem;background:white}.session-card[draggable=true]{cursor:grab}.session-card.dragging{opacity:.5}.session-card h3{margin:0 0 .3rem;font-size:1rem}.session-card p{margin:.25rem 0;color:#59667c}.session-card button{margin-top:.5rem}.agenda-board{display:grid;gap:1rem}.agenda-group{min-height:6rem;padding:.8rem;border:1px dashed #abb6c8;border-radius:.75rem;background:#f7f8fb}.agenda-group.preview-ok{border-color:#168253;background:#eef9f3}.agenda-group.preview-conflict{border-color:#b42318;background:#fff0ee}.agenda-group h3{margin:.1rem 0 .65rem}.agenda-group-list{display:grid;gap:.55rem;margin:0;padding:0;list-style:none}.scheduled-meta{font-size:.88rem}.conflict{margin:1rem 0;padding:1rem;border:1px solid #b42318;border-radius:.65rem;background:#fff0ee;color:#7a271a}.empty{padding:1rem;border-radius:.7rem;background:#f1f4fa}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}dialog{width:min(42rem,calc(100% - 2rem));max-height:calc(100% - 2rem);padding:0;border:0;border-radius:1rem;box-shadow:0 1rem 4rem rgb(20 30 50 / 30%)}dialog::backdrop{background:rgb(10 20 35 / 55%)}dialog form{padding:1.4rem}.dialog-heading{display:flex;justify-content:space-between;gap:1rem}.icon-button{width:2.75rem;padding:0;font-size:1.5rem}.preview-state{padding:.7rem;border-left:.25rem solid #3159d9;background:#edf2ff}.preview-state.ok{border-color:#168253;background:#ebf8f1}.preview-state.error{border-color:#b42318;background:#fff0ee}.optimistic{opacity:.65}.rollback{outline:3px solid #b42318;outline-offset:3px}@media(max-width:48rem){.agenda-header,.agenda-hero,.agenda-toolbar{align-items:flex-start;flex-direction:column}.agenda-header{padding-block:.8rem}.agenda-header nav{width:100%;overflow-x:auto}.agenda-layout{grid-template-columns:1fr}.segmented{flex-wrap:nowrap;max-width:calc(100vw - 4rem);overflow-x:auto}.agenda-toolbar>button{width:100%}.form-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*,:before,:after{scroll-behavior:auto!important;transition:none!important}}\n'

SCHEDULE_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n  <title>Event schedule · SessionBuddy</title>\n  <link rel="stylesheet" href="/product/assets/product.css?v=11"><link rel="stylesheet" href="/schedule/assets/schedule.css?v=7">\n  <script src="/schedule/assets/schedule.js?v=8" defer></script>\n</head>\n<body class="public-body">\n  <a class="skip-link" href="#main">Skip to schedule</a>\n  <header id="site-header" class="public-header"><div class="shell app-header__inner"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true">S</span><span>SessionBuddy</span></a><a id="speakers-link" href="#">Speakers</a></div></header>\n  <main id="main" class="shell page" tabindex="-1">\n    <div class="page-heading"><div><p class="eyebrow">Published program</p><h1 id="title">Event schedule</h1><p id="timezone" class="lede">Loading…</p></div><img id="event-logo" class="event-logo" alt="" hidden></div>\n    <div id="status" class="status" role="status" aria-live="polite">Loading published sessions…</div>\n    <nav class="schedule-filters" aria-label="Schedule views"><button data-view="list" aria-pressed="true">List</button><button data-view="day" class="secondary" aria-pressed="false">Day</button><button data-view="week" class="secondary" aria-pressed="false">Week</button><button data-view="track" class="secondary" aria-pressed="false">Track</button><button data-view="room" class="secondary" aria-pressed="false">Room</button><button data-view="mine" class="secondary" aria-pressed="false">My itinerary <span id="itinerary-count">0</span></button></nav>\n    <div id="schedule" class="schedule"></div><div id="empty" class="empty-state" hidden><strong>No sessions are published yet.</strong></div>\n  </main>\n</body>\n</html>\n'

SCHEDULE_JS = '(() => {\n  "use strict";\n  const match = location.pathname.match(/^\\/(?:embeds\\/)?events\\/([^/]+)\\/schedule$/);\n  let eventId = "";\n  try { eventId = match ? decodeURIComponent(match[1]) : ""; } catch (_) { eventId = ""; }\n  if (!/^[A-Za-z0-9_.-]{1,128}$/.test(eventId)) eventId = "";\n  const embedded = location.pathname.startsWith("/embeds/");\n  const storageKey = `sessionbuddy:itinerary:${eventId}`;\n  const state = { model: null, view: "list", itinerary: new Set() };\n  try { state.itinerary = new Set(JSON.parse(localStorage.getItem(storageKey) || "[]")); } catch (_) { state.itinerary = new Set(); }\n  const byId = (id) => document.getElementById(id);\n  const make = (tag, text, className) => { const node = document.createElement(tag); if (text !== undefined) node.textContent = text; if (className) node.className = className; return node; };\n  function format(value, options) { try { return new Intl.DateTimeFormat(undefined, { timeZone: state.model.event.time_zone, ...options }).format(new Date(value)); } catch (_) { return "Date unavailable"; } }\n  function day(item) { return format(item.start_at_ms, { weekday: "long", month: "long", day: "numeric" }); }\n  function group(item) { if (state.view === "room") return item.room_name; if (state.view === "track") return item.track_name || "No track"; if (["day", "week"].includes(state.view)) return day(item); if (state.view === "mine") return "My itinerary"; return "All sessions"; }\n  function saveItinerary() { localStorage.setItem(storageKey, JSON.stringify([...state.itinerary])); byId("itinerary-count").textContent = String(state.itinerary.size); }\n  function toggleItinerary(id) { if (state.itinerary.has(id)) state.itinerary.delete(id); else state.itinerary.add(id); saveItinerary(); render(); }\n  function render() {\n    const visible = state.view === "mine" ? state.model.items.filter((item) => state.itinerary.has(item.id)) : state.model.items;\n    const groups = new Map();\n    visible.forEach((item) => { const key = group(item); if (!groups.has(key)) groups.set(key, []); groups.get(key).push(item); });\n    const root = byId("schedule"); root.replaceChildren(); root.classList.toggle("week-view", state.view === "week");\n    byId("empty").hidden = visible.length !== 0;\n    byId("empty").querySelector("strong").textContent = state.view === "mine" ? "Choose + on a session to build your itinerary." : "No sessions are published yet.";\n    [...groups].forEach(([name, items]) => {\n      const section = make("section", undefined, "schedule-group"); section.append(make("h2", name));\n      const list = make("ol", undefined, "schedule-list");\n      items.sort((a, b) => a.start_at_ms - b.start_at_ms).forEach((item) => {\n        const row = make("li", undefined, "schedule-item");\n        const time = make("time", `${format(item.start_at_ms, { hour: "numeric", minute: "2-digit" })}–${format(item.end_at_ms, { hour: "numeric", minute: "2-digit" })}`); time.dateTime = new Date(item.start_at_ms).toISOString();\n        const details = document.createElement("div"); details.append(make("h3", item.title), make("p", `${item.speaker_names || "Speaker TBA"} · ${item.room_name}${item.track_name ? ` · ${item.track_name}` : ""}`));\n        if (item.description) details.append(make("p", item.description, "description"));\n        const add = make("button", state.itinerary.has(item.id) ? "✓" : "+", "itinerary-button"); add.type = "button"; add.setAttribute("aria-pressed", String(state.itinerary.has(item.id))); add.setAttribute("aria-label", `${state.itinerary.has(item.id) ? "Remove" : "Add"} ${item.title} ${state.itinerary.has(item.id) ? "from" : "to"} my itinerary`); add.addEventListener("click", () => toggleItinerary(item.id));\n        row.append(time, details, add); list.append(row);\n      }); section.append(list); root.append(section);\n    });\n  }\n  document.querySelectorAll("[data-view]").forEach((button) => button.addEventListener("click", () => { state.view = button.dataset.view; document.querySelectorAll("[data-view]").forEach((item) => { const active = item === button; item.setAttribute("aria-pressed", String(active)); item.classList.toggle("secondary", !active); }); render(); }));\n  async function load() {\n    if (!eventId) throw new Error("Invalid schedule link");\n    let response = await fetch(`/api/v1/public/events/${encodeURIComponent(eventId)}/schedule`, { headers: { accept: "application/json" } });\n    if (response.status === 401 || response.status === 403) {\n      response = await fetch(`/api/v1/events/${encodeURIComponent(eventId)}/schedule`, { credentials: "same-origin", headers: { accept: "application/json" } });\n    }\n    const body = await response.json(); if (!response.ok) throw new Error(body?.error?.message || "Schedule unavailable");\n    state.model = body; document.body.classList.toggle("embedded", embedded);\n    byId("title").textContent = body.event.name; byId("speakers-link").href = `/events/${encodeURIComponent(eventId)}/speakers`;\n    byId("timezone").textContent = body.revision\n      ? `Times shown in ${body.event.time_zone}. Published revision ${body.revision.version}.`\n      : `Times will be shown in ${body.event.time_zone}.`;\n    byId("status").textContent = body.revision\n      ? `${body.items.length} published session${body.items.length === 1 ? "" : "s"}.`\n      : "The organizer has not published the schedule yet.";\n    if (body.event.accent_color) document.documentElement.style.setProperty("--blue", body.event.accent_color);\n    if (body.event.logo_url) { byId("event-logo").src = body.event.logo_url; byId("event-logo").hidden = false; }\n    saveItinerary(); render();\n  }\n  load().catch((error) => { byId("status").textContent = error.message; byId("status").classList.add("error"); });\n})();\n'

SCHEDULE_CSS = '.schedule-filters { display: flex; gap: .5rem; max-width: 100%; overflow-x: auto; margin: 1.25rem 0; padding-bottom: .25rem; }\n.schedule-filters button { min-width: max-content; }\n.schedule { display: grid; gap: 1.15rem; }\n.schedule.week-view { grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr)); align-items: start; }\n.schedule-group { min-width: 0; padding: 1rem; border: 1px solid var(--line); border-radius: .8rem; background: white; box-shadow: var(--shadow); }\n.schedule-group h2 { margin-top: 0; font-size: 1.2rem; }\n.schedule-list { display: grid; gap: .1rem; margin: 0; padding: 0; list-style: none; }\n.schedule-item { min-width: 0; display: grid; grid-template-columns: minmax(7rem,.25fr) minmax(0,1fr) auto; gap: 1rem; align-items: start; padding: 1rem .35rem; border-top: 1px solid var(--line); }\n.schedule-item:first-child { border-top: 0; }\n.schedule-item time { color: #34435c; font-size: .88rem; font-weight: 800; }\n.schedule-item h3 { margin: 0; }\n.schedule-item p { margin: .3rem 0; color: var(--muted); }\n.schedule-item .description { font-size: .88rem; }\n.itinerary-button { width: 2.8rem; min-width: 2.8rem; padding: 0; border: 1px solid #cbd4e2; background: white; color: var(--blue-dark); font-size: 1.25rem; }\n.itinerary-button:hover, .itinerary-button[aria-pressed="true"] { background: #e4ebff; color: #183eae; }\nbody.embedded #site-header { display: none; }\nbody.embedded .page { padding: .75rem; }\nbody.embedded .shell { width: 100%; }\n@media(max-width: 38rem) { .schedule-item { grid-template-columns: 1fr auto; } .schedule-item time { grid-column: 1 / -1; } }\n'

EVENT_WORKSPACE_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Speaker resources · SessionBuddy</title>\n  <link rel="stylesheet" href="/product/assets/product.css?v=11">\n  <link rel="stylesheet" href="/app-shell/assets/app-shell.css?v=3">\n  <script src="/app-shell/assets/app-shell.js?v=4" defer></script>\n  <script src="/admin/workspace/assets/workspace.js?v=1" defer></script>\n</head>\n<body class="app-body">\n  <a class="skip-link" href="#main">Skip to speaker resources</a>\n  <header data-auth-shell></header>\n  <main id="main" class="shell page" tabindex="-1">\n    <div class="page-heading">\n      <div><h1>Speaker resources</h1><p class="lede">Share resources, assign tasks, and connect accepted sessions to Accelevents.</p></div>\n      <a id="onboarding-link" class="button secondary" href="#">View readiness</a>\n    </div>\n    <div id="status" class="status status-compact" role="status" aria-live="polite">Loading…</div>\n    <section class="grid workspace-grid">\n      <article class="card" aria-labelledby="resource-title">\n        <div class="section-heading"><div><p class="eyebrow">Portal content</p><h2 id="resource-title">Resources & wiki</h2></div><span id="resource-count" class="badge">0</span></div>\n        <p class="help">Publish guides, venue notes, or an approved video/document embed to the speaker portal.</p>\n        <form id="resource-form">\n          <label>Title<input name="title" maxlength="200" required></label>\n          <label>URL slug<input name="slug" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="speaker-guide" required></label>\n          <label>Summary<input name="summary" maxlength="500"></label>\n          <label>Page content<textarea name="body_text" maxlength="20000" placeholder="Write the instructions speakers need…"></textarea></label>\n          <label>Approved embed URL <span class="optional">Optional</span><input name="embed_url" type="url" placeholder="https://docs.google.com/…"><small>Google Docs, Drive, Calendar, YouTube, or Vimeo.</small></label>\n          <div class="form-grid"><label>Status<select name="status"><option value="published">Published</option><option value="draft">Draft</option></select></label><label>Order<input name="sort_order" type="number" value="0" min="-1000" max="1000"></label></div>\n          <button>Publish resource</button>\n        </form>\n        <ul id="resource-list" class="item-list" aria-label="Event resources"></ul>\n      </article>\n      <article class="card" aria-labelledby="task-title">\n        <div class="section-heading"><div><p class="eyebrow">Follow-up</p><h2 id="task-title">Custom speaker task</h2></div></div>\n        <p class="help">Assign a request or a short form to one accepted speaker.</p>\n        <form id="task-form">\n          <label>Speaker<select name="event_speaker_id" id="speaker-target" required><option value="">Choose a speaker…</option></select></label>\n          <label>Task title<input name="title" maxlength="200" required></label>\n          <label>Instructions<textarea name="help_text" maxlength="2000"></textarea></label>\n          <label>Due date <span class="optional">Optional</span><input name="due_at" type="datetime-local"></label>\n          <fieldset><legend>Optional response field</legend><label>Question label<input name="field_label" maxlength="200" placeholder="e.g. Dietary requirements"></label><div class="form-grid"><label>Answer type<select name="field_type"><option value="text">Short text</option><option value="textarea">Long text</option><option value="url">URL</option><option value="checkbox">Confirmation</option></select></label><label class="check-label"><input name="field_required" type="checkbox"> Required</label></div></fieldset>\n          <button>Assign task</button>\n        </form>\n      </article>\n      <article class="card wide" aria-labelledby="integration-title">\n        <div class="section-heading"><div><p class="eyebrow">One-way integration</p><h2 id="integration-title">Accelevents</h2></div><span class="badge success">Pull feed</span></div>\n        <p class="help">Generate a read-only API token. Accelevents can pull accepted speakers and sessions using this event ID; unpublished and rejected content is excluded.</p>\n        <div class="integration-grid"><div><strong>Event ID</strong><code id="event-id">—</code></div><div><strong>API base URL</strong><code id="api-base">—</code></div></div>\n        <form id="token-form" class="inline-form"><label>Token label<input name="label" placeholder="Accelevents production feed" maxlength="120" required></label><button>Generate token</button></form>\n        <div id="token-result" class="secret-result" hidden><strong>Copy this token now</strong><code id="token-value"></code><p>It is shown once and stored only as a secure hash.</p></div>\n      </article>\n    </section>\n  </main>\n</body>\n</html>\n'

EVENT_WORKSPACE_JS = '(() => {\n  "use strict";\n  const match = location.pathname.match(/^\\/admin\\/events\\/([^/]+)\\/workspace$/);\n  let eventId = "";\n  try { eventId = match ? decodeURIComponent(match[1]) : ""; } catch (_) { eventId = ""; }\n  const byId = (id) => document.getElementById(id);\n  const state = { csrf: "" };\n\n  function setStatus(message, error = false) {\n    byId("status").textContent = message;\n    byId("status").classList.toggle("error", error);\n  }\n  async function api(path, options = {}) {\n    const response = await fetch(path, { credentials: "same-origin", ...options });\n    const body = await response.json().catch(() => null);\n    if (!response.ok) throw Object.assign(new Error(body?.error?.message || `Request failed (${response.status})`), { status: response.status });\n    return body;\n  }\n  function slug(value) { return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80); }\n  function mutationHeaders() { return { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` }; }\n\n  async function loadResources() {\n    const body = await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/resources`);\n    byId("resource-count").textContent = body.data.length;\n    const nodes = body.data.map((item) => {\n      const li = document.createElement("li");\n      const title = document.createElement("strong"); title.textContent = item.title;\n      const meta = document.createElement("span"); meta.className = "muted"; meta.textContent = `${item.status} · /${item.slug}`;\n      li.append(title, meta); return li;\n    });\n    byId("resource-list").replaceChildren(...nodes);\n  }\n  async function loadTargets() {\n    const body = await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/speaker-targets`);\n    const accepted = body.data.filter((item) => item.selection_status === "accepted");\n    const options = accepted.map((item) => { const option = new Option(`${item.display_name} — ${item.proposal_title}`, item.event_speaker_id); return option; });\n    byId("speaker-target").append(...options);\n  }\n  byId("resource-form").elements.title.addEventListener("input", (event) => {\n    const slugInput = event.currentTarget.form.elements.slug;\n    if (!slugInput.dataset.edited) slugInput.value = slug(event.currentTarget.value);\n  });\n  byId("resource-form").elements.slug.addEventListener("input", (event) => { event.currentTarget.dataset.edited = "true"; });\n  byId("resource-form").addEventListener("submit", async (event) => {\n    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget));\n    try {\n      await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/resources`, { method: "POST", headers: mutationHeaders(), body: JSON.stringify({ title: values.title, slug: values.slug, summary: values.summary, body_text: values.body_text, embed_url: values.embed_url || null, status: values.status, sort_order: Number(values.sort_order) }) });\n      event.currentTarget.reset(); event.currentTarget.elements.sort_order.value = "0"; setStatus("Resource published to the speaker portal."); await loadResources();\n    } catch (error) { setStatus(error.message, true); }\n  });\n  byId("task-form").addEventListener("submit", async (event) => {\n    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget));\n    const fields = values.field_label ? [{ key: "response", label: values.field_label, type: values.field_type, required: Boolean(values.field_required), choices: [] }] : [];\n    const due = values.due_at ? new Date(values.due_at).getTime() : null;\n    try {\n      await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/speaker-tasks`, { method: "POST", headers: mutationHeaders(), body: JSON.stringify({ event_speaker_id: values.event_speaker_id, submission_id: null, title: values.title, help_text: values.help_text, due_at_ms: due, fields }) });\n      event.currentTarget.reset(); setStatus("Custom task assigned to the speaker.");\n    } catch (error) { setStatus(error.message, true); }\n  });\n  byId("token-form").addEventListener("submit", async (event) => {\n    event.preventDefault(); const label = new FormData(event.currentTarget).get("label");\n    try {\n      const body = await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/integrations/accelevents/tokens`, { method: "POST", headers: mutationHeaders(), body: JSON.stringify({ label }) });\n      byId("token-value").textContent = body.token; byId("token-result").hidden = false; setStatus("Read-only integration token generated.");\n    } catch (error) { setStatus(error.message, true); }\n  });\n  async function initialize() {\n    if (!eventId) throw new Error("Invalid event link.");\n    const session = await api("/api/v1/session"); state.csrf = session.csrf_token;\n    byId("event-id").textContent = eventId; byId("api-base").textContent = `${location.origin}/v1`;\n    byId("onboarding-link").href = `/admin/events/${encodeURIComponent(eventId)}/onboarding`;\n    await Promise.all([loadResources(), loadTargets()]); setStatus("Resources ready.");\n  }\n  initialize().catch((error) => { if (error.status === 401) location.assign(`/sign-in?redirect=${encodeURIComponent(location.pathname)}`); else setStatus(error.message, true); });\n})();\n'

SPEAKER_GALLERY_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Speakers · SessionBuddy</title>\n  <link rel="stylesheet" href="/product/assets/product.css?v=11">\n  <script src="/gallery/assets/gallery.js?v=1" defer></script>\n</head>\n<body class="public-body">\n  <a class="skip-link" href="#main">Skip to speakers</a>\n  <header class="public-header"><div class="shell app-header__inner"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true">S</span><span>SessionBuddy</span></a><a id="schedule-link" class="text-link" href="#">View schedule</a></div></header>\n  <main id="main" class="shell page" tabindex="-1">\n    <div class="page-heading"><div><p class="eyebrow">Meet the speakers</p><h1 id="event-name">Event speakers</h1><p id="status" class="lede" role="status" aria-live="polite">Loading the accepted speaker lineup…</p></div><img id="event-logo" class="event-logo" alt="" hidden></div>\n    <section id="speaker-grid" class="speaker-gallery" aria-label="Accepted speakers"></section>\n    <section id="empty" class="empty-state" hidden><strong>The lineup is being prepared.</strong><p>Accepted speakers will appear here as the program is finalized.</p></section>\n  </main>\n</body>\n</html>\n'

SPEAKER_GALLERY_JS = '(() => {\n  "use strict";\n  const match = location.pathname.match(/^(?:\\/embeds)?\\/events\\/([^/]+)\\/speakers$/);\n  document.body.classList.toggle("embedded", location.pathname.startsWith("/embeds/"));\n  let eventId = ""; try { eventId = match ? decodeURIComponent(match[1]) : ""; } catch (_) { eventId = ""; }\n  const byId = (id) => document.getElementById(id);\n  const make = (tag, text, className) => { const node = document.createElement(tag); if (text !== undefined) node.textContent = text; if (className) node.className = className; return node; };\n  function speakerCard(speaker) {\n    const card = document.createElement("article"); card.className = "speaker-card";\n    const media = document.createElement("div"); media.className = "speaker-card__media";\n    if (speaker.headshot_url) { const image = document.createElement("img"); image.src = speaker.headshot_url; image.alt = ""; image.loading = "lazy"; media.append(image); }\n    else media.append(make("span", speaker.display_name.split(/\\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase(), "speaker-initials"));\n    const body = document.createElement("div"); body.className = "speaker-card__body"; body.append(make("h2", speaker.display_name));\n    const role = [speaker.job_title, speaker.company].filter(Boolean).join(" · "); if (role) body.append(make("p", role, "muted"));\n    if (speaker.biography) body.append(make("p", speaker.biography, "speaker-bio"));\n    if (speaker.sessions.length) { const list = document.createElement("ul"); list.className = "session-chips"; speaker.sessions.forEach((session) => list.append(make("li", session.title))); body.append(list); }\n    card.append(media, body); return card;\n  }\n  async function load() {\n    if (!eventId) throw new Error("Invalid speaker gallery link.");\n    const response = await fetch(`/api/v1/public/events/${encodeURIComponent(eventId)}/speakers`, { headers: { accept: "application/json" } });\n    const body = await response.json(); if (!response.ok) throw new Error(body?.error?.message || "Speaker gallery unavailable.");\n    document.documentElement.style.setProperty("--blue", body.event.accent_color || "#3159d9"); byId("event-name").textContent = body.event.name;\n    byId("schedule-link").href = `/events/${encodeURIComponent(eventId)}/schedule`;\n    if (body.event.logo_url) { byId("event-logo").src = body.event.logo_url; byId("event-logo").alt = `${body.event.name} logo`; byId("event-logo").hidden = false; }\n    byId("speaker-grid").replaceChildren(...body.data.map(speakerCard)); byId("empty").hidden = body.data.length !== 0; byId("status").textContent = `${body.data.length} accepted speaker${body.data.length === 1 ? "" : "s"}.`;\n  }\n  load().catch((error) => { byId("status").textContent = error.message; byId("status").classList.add("error-text"); });\n})();\n'

